/* 학습 해설
 * arm64 frame record 정렬·8바이트 조건
 * arm64 스택 추적의 주소 범위·프레임 record·단조 소비·스택 전이·설정별 조회 기술의 원리를 이해합니다.
 * next_frame_record는 fp&0x7이 0인지 먼저 검사합니다. 아래 세 비트가 있으면 8바이트 정렬이 아니므로 -EINVAL입니다. 정렬 검사만 통과했다고 읽지 않고 그 다음 16바이트 전체가 소비 가능한 스택 범위인지 확인합니다.
 * 유효 정렬된 배열 base와 base+1을 비교하세요. fixture는 base+1 경로가 역참조 전에 실패하는지 확인합니다. 이 조건을 16바이트 정렬 강제로 바꾸거나 다른 architecture의 규칙으로 일반화하지 않습니다.
 */
unwind_next_frame_record(struct unwind_state *state)
{
	unsigned long fp = state->fp;
	int err;

	if (fp & 0x7)
		return -EINVAL;

	err = unwind_consume_stack(state, fp, 16);
	if (err)
		return err;

	/*
	 * Record this frame record's values.
	 */
	state->fp = READ_ONCE(*(unsigned long *)(fp));
	state->pc = READ_ONCE(*(unsigned long *)(fp + 8));

	return 0;
}

#endif	/* __ASM_STACKTRACE_COMMON_H */

