/* 학습 해설
 * arm64 IRQ 스택 범위·per-CPU 포인터와 크기
 * arm64 스택 추적의 주소 범위·프레임 record·단조 소비·스택 전이·설정별 조회 기술의 원리를 이해합니다.
 * IRQ getter는 raw_cpu_read(irq_stack_ptr)로 현재 CPU의 스택 시작을 받고 IRQ_STACK_SIZE를 더해 high를 만듭니다. on_irq_stack은 그 범위로 sp·size 전체 포함을 확인합니다. raw getter가 접근 문맥의 CPU 이동을 스스로 막는 것은 아니며 상위 walker가 접근 가능한 문맥을 선택합니다.
 * 모델의 IRQ 배열에서 시작·끝·끝을 넘는 16바이트 객체를 시험합니다. 실제 per-CPU 저장·IRQ 진입·선점 방지는 수행하지 않았으므로 상위 STACKINFO_CPU 조건을 연결해 공부합니다.
 */
static inline struct stack_info stackinfo_get_irq(void)
{
	unsigned long low = (unsigned long)raw_cpu_read(irq_stack_ptr);
	unsigned long high = low + IRQ_STACK_SIZE;

	return (struct stack_info) {
		.low = low,
		.high = high,
	};
}

static inline bool on_irq_stack(unsigned long sp, unsigned long size)
{
	struct stack_info info = stackinfo_get_irq();
	return stackinfo_on_stack(&info, sp, size);
}

static inline struct stack_info stackinfo_get_task(const struct task_struct *tsk)
{
	unsigned long low = (unsigned long)task_stack_page(tsk);
	unsigned long high = low + THREAD_SIZE;

	return (struct stack_info) {
		.low = low,
		.high = high,
	};

