/* 학습 해설
 * arm64 caller 시작·inline과 noinline의 역할
 * arm64 실행 경로를 수집하는 시작 문맥·프레임 순회·주소 복원·BPF·출력·사용자 접근 기술의 원리와 계약을 이해합니다.
 * caller 출발은 builtin frame address 1과 return address 0을 사용합니다. 이 초기화 함수는 항상 inline이고 이를 호출하는 함수는 noinline이어야 한다는 주석이 있습니다. compiler가 어디에 코드를 넣느냐에 따라 caller가 뜻하는 프레임이 달라질 수 있어 함수 annotation도 동작 계약의 일부입니다.
 * arch_stack_walk와 BPF wrapper의 noinline 표시를 확인하세요. fixture는 builtin 결과를 유효 합성 frame 포인터와 PC로 대체하므로 실제 compiler stack frame 생성·최적화 ABI를 검증하지 않습니다.
 */
kunwind_init_from_caller(struct kunwind_state *state)
{
	kunwind_init(state, current);

	state->common.fp = (unsigned long)__builtin_frame_address(1);
	state->common.pc = (unsigned long)__builtin_return_address(0);
}

/*
 * Start an unwind from a blocked task.
 *
 * The unwind will begin at the blocked tasks saved PC (i.e. the caller of
 * cpu_switch_to()).
 *
 * The caller should ensure the task is blocked in cpu_switch_to() for the
 * duration of the unwind, or the unwind will be bogus. It is never valid to
 * call this for the current task.
 */
static __always_inline void
kunwind_init_from_task(struct kunwind_state *state,
		       struct task_struct *task)
{
	kunwind_init(state, task);

	state->common.fp = thread_saved_fp(task);
	state->common.pc = thread_saved_pc(task);

