/* 학습 해설
 * arm64 backtrace 출력·user mode 제외와 참조 균형
 * arm64 실행 경로를 수집하는 시작 문맥·프레임 순회·주소 복원·BPF·출력·사용자 접근 기술의 원리와 계약을 이해합니다.
 * dump_backtrace는 regs가 user mode면 반환하고 task가 NULL이면 current로 바꿉니다. task stack 참조 획득에 실패하면 종료하며 성공하면 Call trace 제목과 주소별 symbol을 출력하고 참조를 반납합니다. 사용자 스택 수집 API와 커널 backtrace 출력의 역할이 다릅니다.
 * user regs·NULL task·없는 stack의 세 분기와 성공 경로를 따라가세요. 모델은 printk 호출 수·getter/putter 균형을 확인하며 실제 log level·%pSb symbol 문자열·console 출력 정책은 기록 모델입니다.
 */
void dump_backtrace(struct pt_regs *regs, struct task_struct *tsk,
		    const char *loglvl)
{
	pr_debug("%s(regs = %p tsk = %p)\n", __func__, regs, tsk);

	if (regs && user_mode(regs))
		return;

	if (!tsk)
		tsk = current;

	if (!try_get_task_stack(tsk))
		return;

	printk("%sCall trace:\n", loglvl);
	arch_stack_walk(dump_backtrace_entry, (void *)loglvl, tsk, regs);

	put_task_stack(tsk);
}

void show_stack(struct task_struct *tsk, unsigned long *sp, const char *loglvl)
{
	dump_backtrace(NULL, tsk, loglvl);
	barrier();
}

