/* 학습 해설
 * arm64 compat 사용자 순회·다음 fp 변환과 엄격 진행
 * arm64 실행 경로를 수집하는 시작 문맥·프레임 순회·주소 복원·BPF·출력·사용자 접근 기술의 원리와 계약을 이해합니다.
 * compat helper도 access_ok·pagefault 구간의 copy·오류 검사를 수행하지만 lr를 user PAC helper 없이 callback에 전달합니다. tail+1>=compat_ptr(buftail.fp)이면 중단하고 그렇지 않으면 변환한 pointer에서 구조체 하나를 빼 다음 tail로 반환합니다. 저장 fp와 실제 record pointer의 차이를 유지해야 합니다.
 * 모델의 low32 mmap에 c0→c1→정지 record를 넣고 303·404의 lr가 전달되는지 확인하세요. 이 검사에서 실제 kernel compat_ptr 구현은 uintptr 변환 모델이며 모든 사용자 주소 표시 규칙을 재현하지 않습니다.
 */
unwind_compat_user_frame(struct compat_frame_tail __user *tail, void *cookie,
				stack_trace_consume_fn consume_entry)
{
	struct compat_frame_tail buftail;
	unsigned long err;

	/* Also check accessibility of one struct frame_tail beyond */
	if (!access_ok(tail, sizeof(buftail)))
		return NULL;

	pagefault_disable();
	err = __copy_from_user_inatomic(&buftail, tail, sizeof(buftail));
	pagefault_enable();

	if (err)
		return NULL;

	if (!consume_entry(cookie, buftail.lr))
		return NULL;

	/*
	 * Frame pointers should strictly progress back up the stack
	 * (towards higher addresses).
	 */
	if (tail + 1 >= (struct compat_frame_tail __user *)
			compat_ptr(buftail.fp))

