/* 학습 해설
 * arm64 사용자 walker 시작·PC 먼저 전달하고 정렬 분기
 * arm64 실행 경로를 수집하는 시작 문맥·프레임 순회·주소 복원·BPF·출력·사용자 접근 기술의 원리와 계약을 이해합니다.
 * 사용자 walker는 regs.pc를 callback에 먼저 전달하고 false면 바로 종료합니다. AARCH64이면 regs[29]에서 tail을 얻고 NULL이 아니며 8바이트 정렬인 동안 반복합니다. compat이면 설정에 따라 compat_fp에서 record 하나를 빼고 4바이트 정렬을 검사합니다. COMPAT가 꺼진 compat 입력은 처음 PC 전달 후 해당 body를 실행하지 않습니다.
 * 용량 1·misaligned fp·compat 설정 0·1을 각각 계산하세요. 모델은 실제 유효 low32 mmap record와 오류 입력의 분기를 확인하며 사용자 compiler의 frame 유지나 실제 kernel user fault를 실행하지 않습니다.
 */
void arch_stack_walk_user(stack_trace_consume_fn consume_entry, void *cookie,
					const struct pt_regs *regs)
{
	if (!consume_entry(cookie, regs->pc))
		return;

	if (!compat_user_mode(regs)) {
		/* AARCH64 mode */
		struct frame_tail __user *tail;

		tail = (struct frame_tail __user *)regs->regs[29];
		while (tail && !((unsigned long)tail & 0x7))
			tail = unwind_user_frame(tail, cookie, consume_entry);
	} else {
#ifdef CONFIG_COMPAT
		/* AARCH32 compat mode */
		struct compat_frame_tail __user *tail;

		tail = (struct compat_frame_tail __user *)regs->compat_fp - 1;
		while (tail && !((unsigned long)tail & 0x3))
			tail = unwind_compat_user_frame(tail, cookie, consume_entry);
#endif
	}
}

