/* 학습 해설
 * arm64 architecture walk 검산·실제 본문과 제공한 실행 문맥
 * arm64 실행 경로를 수집하는 시작 문맥·프레임 순회·주소 복원·BPF·출력·사용자 접근 기술의 원리와 계약을 이해합니다.
 * fixture는 원본 448행 C와 두 헤더의 include를 제거하고 유효 frame 배열·저장 task 값·합성 builtin 출발점·helper 복원 반환·per-CPU 문맥·유효 low32 사용자 mmap으로 연결합니다. 원본 분기와 frame 읽기를 실행했지만 실제 boot·CPU 레지스터·PAC·blocked task·ftrace/kretprobe 내부 구현·SMP 검증은 별도입니다.
 * caller 전달·frame 경계·수집 중단·반환 주소 복원 호출·사용자 접근 오류의 질문을 각각 분리해 공부하세요. 선택 tracing은 graph와 kretprobe를 함께 off/on, compat은 off/on으로 시험하며 모든 독립 설정 조합의 증명은 아닙니다.
 */
noinline noinstr void arch_stack_walk(stack_trace_consume_fn consume_entry,
			      void *cookie, struct task_struct *task,
			      struct pt_regs *regs)
{
	struct kunwind_consume_entry_data data = {
		.consume_entry = consume_entry,
		.cookie = cookie,
	};

	kunwind_stack_walk(arch_kunwind_consume_entry, &data, task, regs);
}

struct bpf_unwind_consume_entry_data {
	bool (*consume_entry)(void *cookie, u64 ip, u64 sp, u64 fp);
	void *cookie;
};

static bool
arch_bpf_unwind_consume_entry(const struct kunwind_state *state, void *cookie)
{
	struct bpf_unwind_consume_entry_data *data = cookie;

	return data->consume_entry(data->cookie, state->common.pc, 0,
				   state->common.fp);
}

