/* 학습 해설
 * 태스크 스택 포인터 조회·수명 참조와 구별
 * 태스크 스택 포인터·수명 참조·thread info 배치·끝 magic·tag·주소 판별·설정별 stub와 override의 사용 원리를 이해합니다.
 * THREAD_INFO_IN_TASK 설정의 task_stack_page는 task->stack을 그대로 반환합니다. 종료할 수 있는 다른 태스크의 스택은 조회 직후 해제될 수 있으므로 원문 주석은 try_get_task_stack을 쓰라고 설명합니다. 주소를 알아내는 연산과 해당 메모리를 사용하는 동안 수명을 유지하는 연산이 다릅니다.
 * task_stack_page와 try_get_task_stack의 호출 목적을 나란히 적으세요. 모델은 유효 배열 주소를 반환하며 실제 태스크 종료 경쟁을 실행하지 않습니다. 상위 stack wrapper의 getter/putter와 연결합니다.
 */
static __always_inline void *task_stack_page(const struct task_struct *task)
{
	return task->stack;
}

#define setup_thread_stack(new,old)	do { } while(0)

static __always_inline unsigned long *end_of_stack(const struct task_struct *task)
{
#ifdef CONFIG_STACK_GROWSUP
	return (unsigned long *)((unsigned long)task->stack + THREAD_SIZE) - 1;
#else
	return task->stack;
#endif
}

#elif !defined(__HAVE_THREAD_FUNCTIONS)

#define task_stack_page(task)	((void *)(task)->stack)

static inline void setup_thread_stack(struct task_struct *p, struct task_struct *org)
{
	*task_thread_info(p) = *task_thread_info(org);
	task_thread_info(p)->task = p;
}

